# Real lines, taken from bills on the live site.
DOCKET_LINES = [
    ("veto_override",
     "Veto Sustained 08/19/2026: RC 152-167 Lacking Necessary Two-Thirds Vote"),
    ("veto_override",
     "Notwithstanding the Governor's Veto, Shall SB 434 Become Law: RC 16Y-8N, "
     "Veto Overridden by necessary two-thirds vote; 08/19/2026"),
    ("unsigned_law",
     "Law Without Signature 08/19/2026; Chapter 344; Effective 08/19/2026; "
     "Art 44, Pt II, NH Constitution"),
    ("unsigned_law",
     "Enacted in accordance with Article 44 PartII of the N.H. Constitution "
     "without the signature of the governor. Chapter 343;I. sec 4 eff 12/1/26"),
    ("interim_report",
     "Interim Study Report: Not Recommended for Future Legislation 06/02/2026 "
     "(Vote 14-0; RC)"),
    ("floor", "Ought to Pass: MA VV 03/06/2026"),
    ("governor", "Vetoed by Governor 07/15/2026"),
    ("amendment", "Amendment # 2026-0503h: AA VV 03/06/2026"),
    ("report", "Committee Report: Ought to Pass with Amendment # 2026-0503h "
               "(Vote 10-0; CC)"),
]


@check("narrative", "the mover is split off a floor action, both chambers' ways",
       needs=("narrative",))
def _split_mover(narrative):
    """The House writes the mover last in parentheses; the Senate writes it
    first with the verb folded in. Before split_mover the Senate name stayed
    inside the motion, so a voice vote was headed "Sen. Abbas Moved Laid on
    Table" as if that were the question put."""
    s = narrative.split_mover
    assert s("Lay on Table (Rep. K. Rice)") == ("Lay on Table", "Rep. K. Rice")
    assert s("Sen. Abbas Moved Laid on Table") == ("Laid on Table", "Sen. Abbas")
    assert s("Sen. Fuller Clark Moved to Concur with the House Amendment") == \
        ("Concur with the House Amendment", "Sen. Fuller Clark")
    assert s("Sen. Innis Accedes to House Request for Committee of Conference") == \
        ("Accedes to House Request for Committee of Conference", "Sen. Innis")
    assert s("Sen. Birdsell moved to call the question") == \
        ("call the question", "Sen. Birdsell")
    assert s("Ought to Pass") == ("Ought to Pass", "")
    return "ok", "House parenthetical and Senate leading name both split"


@check("narrative", "real docket lines classify correctly", needs=("narrative",))
def _classify(narrative):
    wrong = []
    for want, line in DOCKET_LINES:
        got = narrative.classify(line)["_type"]
        if got != want:
            wrong.append(f"{want}->{got}: {line[:44]}")
    assert not wrong, "; ".join(wrong)
    return "ok", f"{len(DOCKET_LINES)} lines, every type as expected"


@check("narrative", "amendments stage by what the line says", needs=("narrative",))
def _amend_stage(narrative):
    cases = [("Amendment # 2026-0503h: AA VV 03/06/2026", "floor"),
             ("Committee Amendment # 2026-0777h, AA, VV; 03/06/2026", "committee"),
             ("Enrolled Bill Amendment # 2026-2001e Adopted, VV, "
              "(In recess 06/26/2026)", "governor")]
    wrong = []
    for line, want in cases:
        ev = narrative.classify(line)
        ev["body"] = "H"
        got = narrative.stage_of(ev)[1]
        if got != want:
            wrong.append(f"{line[:26]}... -> {got}, wanted {want}")
    assert not wrong, "; ".join(wrong)
    return "ok", "bare->floor, committee->committee, enrolled->governor"


@check("narrative", "an amendment row that states no rejection is not called rejected",
       needs=("narrative",))
def _amend_not_rejected(narrative):
    """A row with no motion the amendment pattern reads was written "was
    rejected" -- 192 rows on 118 bills of 2007-2026, falsely for 150. HB 266
    of 2026 read that 2026-0720s was rejected and then adopted: the first
    row is the Senate announcing it. The rest are words the pattern does not
    take. Every line below is a real docket row."""
    N = narrative
    from datetime import datetime as _dt

    def one(line, body="S"):
        ev = N.classify(line)
        ev["body"] = body
        return N.describe(ev, body) or ""

    def history(bill, lines, session="2026"):
        # A database-era session is read by that era's own vocabulary, the
        # way the real rows are; each row is entered a minute after the one
        # before it, on one day.
        rows = [{"lsr": "", "session": session, "body": b, "desc": d,
                 "created": _dt(int(session), 2, 19, 10, i), "flags": []}
                for i, (b, d) in enumerate(lines)]
        keep = N.TERM
        try:
            N.TERM = N.P.term_of(session)
            return N.build(bill, rows)["narrative"]
        finally:
            N.TERM = keep

    bad = []
    for line, body, want, never in (
            ("Sen. Watters Withdraws Floor Amendment #2018-1018s ; 03/15/2018; SJ 8", "S",
             "was withdrawn", "rejected"),
            ("Committee Amendment #2020-1471s : Sections 1-6 and Sections 9-24, RC 14Y-10N, AA; "
             "06/16/2020; SJ 8", "S", "Part of the committee's amendment (2020-1471s) was adopted "
             "on a roll call 14–10", "rejected"),
            ("Committee Amendment #2020-1471s : Sections 7 and 24, RC 12Y-12N, AF; 06/16/2020; "
             "SJ 8", "S", "was rejected on a roll call 12–12", "adopted"),
            # Alone, a row cannot say the docket holds no vote: that is a
            # claim about the bill's other rows, which only build() reads.
            ("Sen. Rosenwald Floor Amendment # 2025-0752s; 03/06/2025;  SJ 6", "S",
             "proposed a floor amendment (2025-0752s)", "rejected|no vote"),
            ("Sen. Soucy Floor Amendment #2016-1160s , Not Voted On; 03/24/2016; SJ 10", "S",
             "it was not voted on", "rejected"),
            ("Floor Amendment #2014-1812h (Rep. Hoell) MF RC 110-205", "H",
             "was rejected on a roll call 110–205", "adopted"),
            # A calendar's notice of an amendment to come is not a floor
            # amendment offered (HB 1661 of 2022).
            ("Amendment #2022-1475s to HB 1661 will be proposed; SC 16", "S",
             "Notice was given that an amendment (2022-1475s) would be proposed",
             "floor|rejected|no vote")):
        got = one(line, body)
        if (want not in got or any(x in got for x in never.split("|"))
                or "Offered," in got or "Withdraws," in got):
            bad.append(f"{line[:40]}... -> {got!r}")
    got = history("HB266", [
        ("S", "Sen. Birdsell Floor Amendment # 2026-0720s; 02/19/2026;  SJ 4"),
        ("S", "Chair Ruled Sections of Amendment # 2026-0720s Non-Germane, 02/19/2026;  SJ 4"),
        ("S", "Sen. Birdsell Floor Amendment # 2026-0720s, AA, VV; 02/19/2026;  SJ 4")])
    if "rejected" in got or got.count("2026-0720s") != 1:
        bad.append(f"HB 266: {got!r}")
    got = history("SB535", [
        ("S", "Sen. Soucy Floor Amendment #2016-1160s , Not Voted On; 03/24/2016; SJ 10"),
        ("S", "Sen. Soucy Floor Amendment #2016-1160s , AF, VV; 03/24/2016; SJ 10")])
    if "not voted on" in got or "rejected on a voice vote" not in got:
        bad.append(f"SB 535: {got!r}")
    # "THE DOCKET RECORDS NO VOTE ON IT" is a claim about every row of the
    # bill, and was made on six bills whose other rows held the vote: the
    # number spelled another way, or on a row that is not an amendment row.
    # Each history below is the real bill's rows for that amendment.
    for bill, session, lines, want, never in (
            # Decided on rows that begin with the number, and passed with it.
            ("SB318", "2018", [
                ("S", "Sen. Bradley Offered Floor Amendment #2018-1198s ; 03/22/2018; SJ 10"),
                ("S", "Sen. Feltes Moved to divide the Question on 2018-1198s; 03/22/2018; SJ 10"),
                ("S", "2018-1198s All Remaining Sections, and Sec.13, RC 11Y-10N, Adopted; "
                      "03/22/2018; SJ 10"),
                ("S", "Ought to Pass with Amendment 2018-1198s, RC 11Y-10N, MA; OT3rdg; "
                      "03/22/2018; SJ 10")],
             "proposed a floor amendment (2018-1198s)", "no vote|rejected"),
            # "2013-1554h" announced in May, "1554h" rejected in June: told once.
            ("SCR1", "2013", [
                ("H", "Floor Amendment #2013-1554h(NT) (Rep Cushing); HJ41, PG.1410-1412"),
                ("H", "Floor Amendment #1554h(NT) (Rep Cushing): AF VV; HJ52, PG.1709-1711")],
             "(1554h) was rejected on a voice vote", "no vote|2013-1554h"),
            ("HB422", "2014", [
                ("S", "Sen. Boutin Floor Amendment #2014-1550s"),
                ("S", "Sen. Boutin Withdrew Floor Amendment 1550s")],
             "it was later withdrawn", "no vote|rejected"),
            ("SB119", "2025", [
                ("S", "Sen. Rosenwald Floor Amendment # 2025-0752s; 03/06/2025;  SJ 6"),
                ("S", "Chair Ruled Sections of Amendment # 2025-0752s Non-Germane, "
                      "03/06/2025;  SJ 6")],
             "the chair ruled sections of it non-germane", "no vote|rejected"),
            # Where nothing else names it, it is still said (SB 296 of 2014).
            ("SB296", "2014", [
                ("H", "Floor Amendment #2014-1494h (Rep. Baldasaro)")],
             "the docket records no vote on it", "rejected"),
            # A withdrawn amendment is one of the day's run, and the count
            # says so: HB 1 of 2011 read "took up 13" where it took up 16.
            ("HB1", "2011", [
                ("H", "Floor Amendment #2011-1261h (Rep Foose) Failed, RC 106-251; HJ 35, PG.1225-1227"),
                ("H", "Floor Amendment #2011-1306h (Rep Emerson), Withdrawn; HJ 35, PG.1227-1230"),
                ("H", "Floor Amendment #2011-1321h (Rep Hatch) Failed, RC 107-254; HJ 35, PG.1230-1232"),
                ("H", "Floor Amendment #2011-1322h (Rep Hatch) Failed, RC 106-249; HJ 35, PG.1232-1234")],
             "took up 4 floor amendments", "took up 3|A floor amendment (2011-1306h)"),
            # The database era reads "Div." as a division and leaves the
            # tally on the row: HB 1487 of 2012.
            ("HB1487", "2012", [
                ("S", "Sen. Bradley Floor Amendment #2012-1903s, Div. 16Y-8N, AA; SJ 12, Pg.439")],
             "adopted on a division vote 16–8", "rejected")):
        got = history(bill, lines, session)
        if want not in got or any(x in got for x in never.split("|")):
            bad.append(f"{bill} of {session}: {got!r}")
    assert not bad, "; ".join(bad)
    return "ok", ("an announcement gives way to the row that decides it, however it spells "
                  "the number; no vote is claimed while another row names it; withdrawn, not "
                  "voted on, part of an amendment and codes out of order read as they say")


@check("narrative", "veto and enactment sentences render", needs=("narrative",))
def _veto_sentences(narrative):
    out = []
    for line, body in ((DOCKET_LINES[0][1], "H"), (DOCKET_LINES[1][1], "S"),
                       (DOCKET_LINES[2][1], "H"), (DOCKET_LINES[4][1], "H")):
        s = narrative.describe(narrative.classify(line), body)
        assert s, f"no sentence for {line[:40]}"
        out.append(s)
    assert "sustained" in out[0], "House veto line lost its outcome"
    assert "override the governor" in out[1], "Senate override line lost its outcome"
    assert "without the governor" in out[2], "unsigned law line lost its meaning"
    return "ok", out[1][:66] + "..."


@check("narrative", "motion movers expand, but only when unambiguous",
       needs=("narrative",))
def _movers(narrative):
    roster = [{"name": "Germana, Nicholas", "chamber": "H"},
              {"name": "Osborne, Jason", "chamber": "H"},
              {"name": "Osborne, Marjorie", "chamber": "H"},
              {"name": "Altschiller, Debra", "chamber": "S"}]
    tmp = Path(tempfile.mkdtemp()) / "roster.json"
    tmp.write_text(json.dumps(roster), encoding="utf-8")
    keep = narrative.MEMBERS
    try:
        narrative.MEMBERS = narrative.load_members(tmp)
        got = [narrative.expand_mover(x) for x in
               ("Rep. N. Germana", "Sen. D. Altschiller", "Rep. Osborne")]
        assert got[0] == "Rep. Nicholas Germana", got[0]
        assert got[1] == "Sen. Debra Altschiller", got[1]
        assert got[2] == "Rep. Osborne", f"two Osbornes, picked one: {got[2]}"
        narrative.MEMBERS = {}
        assert narrative.expand_mover("Rep. N. Germana") == "Rep. N. Germana"
    finally:
        narrative.MEMBERS = keep
        shutil.rmtree(tmp.parent, ignore_errors=True)
    return "ok", "expanded 2, left the shared surname alone, no roster is a no-op"


# A SECOND COMMITTEE'S WORK UNDER ITS OWN HEADING (3 October 2026). Real
# rows, copied from the dockets on disk: Docket.txt lines 1662, 1992, 3594,
# 3788 and 5193 (SB 286 of 2025) and 6942, 7406, 7407 and 7563 (HB 517);
