            {"type": "floor", "date": "2001-06-26", "body": "S", "raw": "Sen. McCarley Moved Non Adopt RC 11Y-13N, MF", "action": "Non Adopt", "motion": "MF", "vote_kind": "RC", "yeas": "11", "nays": "13", "mover": "Sen. McCarley", "cite": "SJ 19"},
